import React, { useEffect, useState } from "react";
import { toast } from "react-toastify";
import bannerService from "../../services/bannerService";
import uploadService from "../../services/uploadService";
import { resolveImageUrl } from "../../components/ProductCard";
import Loader from "../../components/Loader";

const emptyForm = { title: "", image: "", link: "", position: 1, status: "PUBLISHED" };

export default function BannerManagementPage() {
  const [banners, setBanners] = useState([]);
  const [loading, setLoading] = useState(true);
  const [showModal, setShowModal] = useState(false);
  const [editingId, setEditingId] = useState(null);
  const [form, setForm] = useState(emptyForm);
  const [saving, setSaving] = useState(false);
  const [uploading, setUploading] = useState(false);

  const loadBanners = async () => {
    setLoading(true);
    try {
      const res = await bannerService.getAllAdmin();
      setBanners(res.data);
    } catch (err) {
      toast.error("Không thể tải danh sách banner");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => { loadBanners(); }, []);

  const openCreate = () => {
    setEditingId(null);
    setForm(emptyForm);
    setShowModal(true);
  };

  const openEdit = (b) => {
    setEditingId(b.id);
    setForm({ title: b.title, image: b.image, link: b.link || "", position: b.position, status: b.status });
    setShowModal(true);
  };

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleImageSelect = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    setUploading(true);
    try {
      const res = await uploadService.uploadImage(file);
      setForm((prev) => ({ ...prev, image: res.data.url }));
      toast.success("Tải ảnh banner lên thành công");
    } catch (err) {
      toast.error("Lỗi tải ảnh");
    } finally {
      setUploading(false);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setSaving(true);
    try {
      if (editingId) {
        await bannerService.update(editingId, form);
        toast.success("Cập nhật banner thành công");
      } else {
        await bannerService.create(form);
        toast.success("Thêm banner mới thành công");
      }
      setShowModal(false);
      loadBanners();
    } catch (err) {
      toast.error("Có lỗi xảy ra");
    } finally { setSaving(false); }
  };

  const handleToggle = async (id) => {
    try {
      await bannerService.toggleVisibility(id);
      loadBanners();
    } catch (err) { toast.error("Không đổi được trạng thái"); }
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Xóa banner này?")) return;
    try {
      await bannerService.delete(id);
      toast.success("Đã xóa");
      loadBanners();
    } catch (err) { toast.error("Lỗi xóa banner"); }
  };

  return (
    <div>
      <div className="flex items-center justify-between mb-6">
        <h1 className="font-display text-2xl text-ink">Quản lý Banner Slider</h1>
        <button onClick={openCreate} className="bg-ember text-white text-sm font-semibold px-4 py-2 rounded-md">+ Thêm Banner</button>
      </div>

      {loading ? <Loader /> : (
        <div className="bg-white border rounded-xl overflow-hidden">
          <table className="w-full text-sm text-left">
            <thead className="bg-gray-50 text-steel">
              <tr>
                <th className="px-4 py-3">Hình ảnh / Tiêu đề</th>
                <th className="px-4 py-3">Vị trí số</th>
                <th className="px-4 py-3">Đường dẫn khi click</th>
                <th className="px-4 py-3">Trạng thái</th>
                <th className="px-4 py-3 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody className="divide-y">
              {banners.map((b) => (
                <tr key={b.id}>
                  <td className="px-4 py-3">
                    <div className="flex items-center gap-3">
                      <img src={resolveImageUrl(b.image)} className="w-24 h-10 rounded object-cover border" alt="" />
                      <span className="font-medium text-ink">{b.title}</span>
                    </div>
                  </td>
                  <td className="px-4 py-3 text-steel">{b.position}</td>
                  <td className="px-4 py-3 text-steel">{b.link || "-"}</td>
                  <td className="px-4 py-3">
                    <button onClick={() => handleToggle(b.id)} className={`text-xs font-semibold px-2 py-1 rounded-full ${b.status === "PUBLISHED" ? "bg-green-100 text-green-700" : "bg-gray-200 text-steel"}`}>
                      {b.status === "PUBLISHED" ? "Đang hiện" : "Đang ẩn"}
                    </button>
                  </td>
                  <td className="px-4 py-3 text-right space-x-3">
                    <button onClick={() => openEdit(b)} className="text-blue-600">Sửa</button>
                    <button onClick={() => handleDelete(b.id)} className="text-red-500">Xóa</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      {showModal && (
        <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4">
          <div className="bg-white rounded-xl w-full max-w-xl p-6">
            <h2 className="text-xl mb-4">{editingId ? "Sửa Banner" : "Thêm Banner Mới"}</h2>
            <form onSubmit={handleSubmit} className="space-y-3">
              <div>
                <label className="block text-sm font-medium mb-1">Tiêu đề quảng cáo</label>
                <input name="title" value={form.title} onChange={handleChange} required className="w-full border rounded px-3 py-2" />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Ảnh Banner</label>
                <div className="flex gap-4 items-center">
                  <img src={resolveImageUrl(form.image) || "https://placehold.co/120x50"} className="w-32 h-12 rounded object-cover border" alt="" />
                  <input type="file" onChange={handleImageSelect} disabled={uploading} className="text-sm" />
                </div>
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Đường dẫn khi click (Link điều hướng)</label>
                <input name="link" value={form.link} onChange={handleChange} placeholder="Ví dụ: /products hoặc http://..." className="w-full border rounded px-3 py-2" />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Vị trí sắp xếp (Thứ tự tăng dần)</label>
                <input type="number" name="position" value={form.position} onChange={handleChange} className="w-full border rounded px-3 py-2" />
              </div>
              <div>
                <label className="block text-sm font-medium mb-1">Trạng thái</label>
                <select name="status" value={form.status} onChange={handleChange} className="w-full border rounded px-3 py-2">
                  <option value="PUBLISHED">Hiển thị</option>
                  <option value="HIDDEN">Ẩn</option>
                </select>
              </div>
              <div className="flex justify-end gap-3 pt-4">
                <button type="button" onClick={() => setShowModal(false)} className="text-steel">Hủy</button>
                <button type="submit" disabled={saving || uploading} className="bg-ember text-white px-5 py-2 rounded">Lưu lại</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}
